/**
 * The Drizzle schema.
 *
 * This mirrors replica/schema.sql table for table, column for column. The
 * SQL file is the reference; this is the typed version of the same thing,
 * and the migration in ../migrations is generated from it.
 *
 * Conventions, carried over from the SQL:
 *   * every id is a uuid, generated by the database
 *   * every owned row carries org_id
 *   * every foreign key has an explicit on delete rule
 *   * timestamps are timestamptz, in UTC
 *   * status columns are text with a check constraint, not a pg enum, so
 *     adding a value is a migration rather than an ALTER TYPE lock
 */

import { relations, sql } from "drizzle-orm";
import {
  bigint,
  boolean,
  check,
  date,
  index,
  inet,
  integer,
  jsonb,
  pgTable,
  primaryKey,
  smallint,
  text,
  timestamp,
  uniqueIndex,
  uuid,
  varchar,
} from "drizzle-orm/pg-core";

import {
  account,
  apikey,
  invitation,
  jwks,
  member,
  organization,
  session,
  user,
  verification,
} from "./auth-schema.ts";

const createdAt = () => timestamp("created_at", { withTimezone: true }).notNull().defaultNow();
const updatedAt = () => timestamp("updated_at", { withTimezone: true }).notNull().defaultNow();

/* -------------------------------------------------------------------------
 * Tenancy
 *
 * The organization itself belongs to better-auth. What belongs to us is the
 * things a workspace needs that an identity provider has no opinion about:
 * which plan it is on, and the time zone its reports are counted in.
 * ------------------------------------------------------------------------- */

export const orgSettings = pgTable(
  "org_settings",
  {
    orgId: uuid("org_id")
      .primaryKey()
      .references(() => organization.id, { onDelete: "cascade" }),
    planId: uuid("plan_id")
      .notNull()
      .references(() => plans.id, { onDelete: "restrict" }),
    timezone: text("timezone").notNull().default("UTC"),
    isPersonal: boolean("is_personal").notNull().default(true),
    updatedAt: updatedAt(),
  },
  (table) => [index("org_settings_plan_idx").on(table.planId)],
);

export const plans = pgTable("plans", {
  id: uuid("id").primaryKey().defaultRandom(),
  code: text("code").notNull().unique(),
  name: text("name").notNull(),
  limits: jsonb("limits").notNull().default({}),
  features: jsonb("features").notNull().default({}),
  createdAt: createdAt(),
});

export const groups = pgTable(
  "groups",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: uuid("org_id")
      .notNull()
      .references(() => organization.id, { onDelete: "cascade" }),
    name: text("name").notNull(),
    slug: text("slug").notNull(),
    isDefault: boolean("is_default").notNull().default(false),
    preferences: jsonb("preferences").notNull().default({}),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [
    uniqueIndex("groups_org_slug_key").on(table.orgId, table.slug),
    index("groups_org_idx").on(table.orgId),
    // Exactly one default group per organization.
    uniqueIndex("groups_one_default_per_org").on(table.orgId).where(sql`is_default`),
  ],
);

export const deletedAccounts = pgTable(
  "deleted_accounts",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: uuid("user_id"),
    emailHash: text("email_hash").notNull().unique(),
    deletedAt: createdAt(),
    purgeAfter: timestamp("purge_after", { withTimezone: true }).notNull(),
  },
  (table) => [index("deleted_accounts_purge_idx").on(table.purgeAfter)],
);

export const organizationCounters = pgTable("organization_counters", {
  orgId: uuid("org_id")
    .primaryKey()
    .references(() => organization.id, { onDelete: "cascade" }),
  linksCount: integer("links_count").notNull().default(0),
  qrCodesCount: integer("qr_codes_count").notNull().default(0),
  pagesCount: integer("pages_count").notNull().default(0),
  customBackHalvesCount: integer("custom_back_halves_count").notNull().default(0),
  updatedAt: updatedAt(),
});

/* -------------------------------------------------------------------------
 * Domains
 * ------------------------------------------------------------------------- */

export const domains = pgTable(
  "domains",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    // null means a shared, system-wide domain
    orgId: uuid("org_id").references(() => organization.id, { onDelete: "cascade" }),
    host: text("host").notNull().unique(),
    kind: text("kind").notNull().default("custom"),
    isActive: boolean("is_active").notNull().default(true),
    dnsRecords: jsonb("dns_records").notNull().default([]),
    verificationStatus: text("verification_status").notNull().default("pending"),
    verifiedAt: timestamp("verified_at", { withTimezone: true }),
    lastDnsCheckAt: timestamp("last_dns_check_at", { withTimezone: true }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [
    index("domains_org_idx").on(table.orgId),
    index("domains_active_idx").on(table.isActive, table.kind),
    check("domains_kind_check", sql`kind in ('default','custom','bsd')`),
    check(
      "domains_verification_check",
      sql`verification_status in ('pending','verified','failed')`,
    ),
  ],
);

/* -------------------------------------------------------------------------
 * Reserved codes
 * The app and the short links share one host, so a user-chosen back-half must
 * never shadow an app route.
 * ------------------------------------------------------------------------- */

export const reservedCodes = pgTable("reserved_codes", {
  code: text("code").primaryKey(),
  reason: text("reason"),
  createdAt: createdAt(),
});

