export const links = pgTable(
  "links",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: uuid("org_id")
      .notNull()
      .references(() => organization.id, { onDelete: "cascade" }),
    groupId: uuid("group_id")
      .notNull()
      .references(() => groups.id, { onDelete: "cascade" }),
    domainId: uuid("domain_id")
      .notNull()
      .references(() => domains.id, { onDelete: "restrict" }),
    code: text("code").notNull(),
    longUrl: text("long_url").notNull(),
    title: text("title"),
    // The back-half history: a new back-half mints a new row that shares the
    // root id. The old code keeps working and keeps its own numbers.
    rootLinkId: uuid("root_link_id"),
    version: integer("version").notNull().default(1),
    campaignId: uuid("campaign_id").references(() => campaigns.id, { onDelete: "set null" }),
    channelId: uuid("channel_id").references(() => channels.id, { onDelete: "set null" }),
    utmParams: jsonb("utm_params").notNull().default({}),
    tags: text("tags").array().notNull().default(sql`'{}'::text[]`),
    archivedAt: timestamp("archived_at", { withTimezone: true }),
    hiddenAt: timestamp("hidden_at", { withTimezone: true }),
    expiresAt: timestamp("expires_at", { withTimezone: true }),
    clickCount: bigint("click_count", { mode: "number" }).notNull().default(0),
    createdBy: uuid("created_by").references(() => user.id, { onDelete: "set null" }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [
    uniqueIndex("links_domain_code_key").on(table.domainId, table.code),
    index("links_org_created_idx").on(table.orgId, table.createdAt),
    index("links_group_created_idx").on(table.groupId, table.createdAt),
    index("links_root_idx").on(table.rootLinkId),
    index("links_campaign_idx").on(table.campaignId),
    index("links_channel_idx").on(table.channelId),
    index("links_expires_idx").on(table.expiresAt).where(sql`expires_at is not null`),
    index("links_active_idx").on(table.orgId).where(sql`archived_at is null and hidden_at is null`),
    check("links_code_format_check", sql`code ~ '^[A-Za-z0-9_-]{2,255}$'`),
  ],
);

