export const pageTemplates = pgTable(
  "page_templates",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    slug: text("slug").notNull().unique(),
    name: text("name").notNull(),
    category: text("category"),
    content: jsonb("content").notNull().default({}),
    appearance: jsonb("appearance").notNull().default({}),
    thumbnailUrl: text("thumbnail_url"),
    isOfficial: boolean("is_official").notNull().default(false),
    createdAt: createdAt(),
  },
  (table) => [index("page_templates_category_idx").on(table.category)],
);

export const pages = pgTable(
  "pages",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: uuid("org_id")
      .notNull()
      .references(() => organization.id, { onDelete: "cascade" }),
    groupId: uuid("group_id")
      .notNull()
      .references(() => groups.id, { onDelete: "cascade" }),
    domainId: uuid("domain_id").references(() => domains.id, { onDelete: "set null" }),
    title: text("title").notNull(),
    slug: text("slug").notNull(),
    status: text("status").notNull().default("draft"),
    appearance: jsonb("appearance").notNull().default({}),
    seo: jsonb("seo").notNull().default({}),
    scheduledFor: timestamp("scheduled_for", { withTimezone: true }),
    publishedAt: timestamp("published_at", { withTimezone: true }),
    createdBy: uuid("created_by").references(() => user.id, { onDelete: "set null" }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [
    uniqueIndex("pages_domain_slug_key")
      .on(table.domainId, table.slug)
      .where(sql`domain_id is not null`),
    uniqueIndex("pages_org_slug_key").on(table.orgId, table.slug).where(sql`domain_id is null`),
    index("pages_org_created_idx").on(table.orgId, table.createdAt),
    index("pages_status_idx").on(table.status, table.scheduledFor).where(sql`status = 'scheduled'`),
    check("pages_status_check", sql`status in ('draft','published','scheduled')`),
  ],
);

